"updateUrlHistory = function() {

    var form = ijf.main.outerForm.name;
    var item = "";
    if (ijf.currentItem)  item = "&itemId=" + ijf.currentItem.key;

    if (form.indexOf("List") > -1) item = "";

    var formEncoded = encodeURIComponent(form);

    var currentLocation = window.location.pathname + window.location.search;
    var testLocation = '/plugins/servlet/iforms?formId=' + formEncoded + item;
    if (currentLocation == testLocation) {
        return;
    } else {
        history.pushState({}, 'LIS', '/plugins/servlet/iforms?formId=' + form + item);
    }

}"

"onTitleSearchChange= function(inField)
{

  ijf.session["focusOnControl"]="ijfContent_ctr_1_6,8";

  var titleSearchSessionId = ijf.session["titleSearchSessionId"];
  if(titleSearchSessionId)
  {
      window.clearTimeout(titleSearchSessionId);
  }

   var n = inField.target.value;
   var delayThis = function()
   {


  var filterObj = {};

  if(n.length==0)
  {
     filterObj = {"remove":["text"]};
  }
  else
  {
     filterObj =  {"set":[{"text":"\"~"+n+"*\""}]};
  }

      ijf.session["ijfContent_fld_3,2"]=filterObj;


   //with radio, cannot just reset the form because the group needs to complete...set timeout for +200ms
     var resetForm = function(){   
                 ijf.main.renderForm("ijfContent", ijf.main.outerForm.name, false, ijf.currentItem);
                  ijfUtils.hideProgress();
    };
     ijfUtils.showProgress();
     window.setTimeout(resetForm,50);
  }
  titleSearchSessionId =  window.setTimeout(delayThis,1000);
  ijf.session["titleSearchSessionId"] = titleSearchSessionId;

   return true;
} "

